package com.huntmaster;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.*;

public class DagannothComponentCollectorTest
{
    @Test public void interleavedIdenticalTotalsHaveSeparateBaselinesAndEvidenceOnlyReports()
    {
        List<EncounterObservation.Snapshot> reports = new ArrayList<>();
        DagannothComponentCollector c = new DagannothComponentCollector(reports::add);
        String id = UUID.randomUUID().toString();
        String[] names = {"Rex", "Prime", "Supreme"};
        for (String name : names)
        {
            assertTrue(c.npc("Dagannoth " + name, false, "Example", id, 100, 1000));
        }
        for (String name : names)
        {
            assertTrue(c.counter("Your Dagannoth " + name + " kill count is: 50.", "Example", id, 101, 1600));
        }
        for (String name : names)
        {
            assertTrue(c.npc("Dagannoth " + name, true, "Example", id, 102, 2200));
        }
        c.advance(110);
        assertEquals(3, reports.size());
        assertEquals(3, reports.stream().map(r -> r.detectorVersion).distinct().count());
        for (EncounterObservation.Snapshot r : reports)
        {
            assertEquals("Dagannoth Kings", r.boss);
            assertTrue(r.evidenceOnly);
            assertNull(r.creditEventId);
            assertNull(r.signals.get(1).previous);
            assertEquals("beta_candidate", EncounterReportCodec.encode(r).get("trackingMode").getAsString());
        }
        c.counter("Your Dagannoth Rex kill count is: 51.", "Example", id, 120, 13000);
        c.advance(130);
        assertEquals(Integer.valueOf(50), reports.get(3).signals.get(0).previous);
        c.interrupt(131, EncounterObservation.Reason.LOGOUT);
        c.counter("Your Dagannoth Rex kill count is: 52.", "Example", id, 140, 25000);
        c.advance(150);
        assertNull(reports.get(4).signals.get(0).previous);
        assertFalse(c.counter("Your Dagannoth Kings kill count is: 820.", "Example", id, 151, 26000));
        assertFalse(c.npc("Spinolyp", false, "Example", id, 151, 26000));
    }
    @Test public void assignmentChangeDoesNotReuseCounterOrOtherKingSignals()
    {
        List<EncounterObservation.Snapshot> reports = new ArrayList<>();
        DagannothComponentCollector c = new DagannothComponentCollector(reports::add);
        String old = UUID.randomUUID().toString(), next = UUID.randomUUID().toString();
        c.counter("Your Dagannoth Rex kill count is: 50.", "Example", old, 100, 1000);
        c.npc("Dagannoth Prime", false, "Example", old, 101, 1600);
        c.counter("Your Dagannoth Rex kill count is: 51.", "Example", next, 102, 2200);
        c.advance(112);
        EncounterObservation.Snapshot latest = reports.get(reports.size() - 1);
        assertEquals(UUID.fromString(next), latest.assignmentId);
        assertEquals(1, latest.signals.size());
        assertNull(latest.signals.get(0).previous);
    }
}

package com.huntmaster;

import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Collections;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import net.runelite.client.RuneLite;
import net.runelite.client.util.Filepath;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class KcBaselineMigrationTest
{
    private Filepath root;
    private KcBaselineStore store;

    @Before public void isolateRuneLiteHome() throws Exception
    {
        // Gradle sets both properties before RuneLite initializes its static paths.
        // Refuse to mutate anything when run from an unconfigured IDE test runner.
        String configured = System.getProperty("huntmaster.testHome");
        assertNotNull("Run via Gradle with an isolated test home", configured);
        Path home = Paths.get(configured).toAbsolutePath().normalize();
        assertEquals(home, Paths.get(System.getProperty("user.home")).toAbsolutePath().normalize());
        assertEquals(home.resolve(".runelite"), RuneLite.RUNELITE_DIR.toPath().toAbsolutePath().normalize());
        root = Filepath.Unchecked.getRooted(RuneLite.RUNELITE_DIR.toPath());
        root.createDirectories();
        clearFixtures();
        store = new HuntmasterPlugin().createBaselineStore();
    }

    @After public void cleanup() throws Exception
    {
        if (store != null) store.close();
        if (root != null) clearFixtures();
    }

    @Test public void existingLegacyCheckpointMigratesAndSurvivesRestart() throws Exception
    {
        Filepath legacy = root.join("huntmaster", "kc-baselines");
        legacy.createDirectories();
        legacy.joinSegment(KcBaselineStoreTest.filename("account", "boss")).write("257");
        assertFalse(root.join("plugin-data", "huntmaster").exists());
        assertEquals(Integer.valueOf(257), load().get("boss"));
        assertFalse(root.join("huntmaster").exists());
        assertTrue(root.join("plugin-data", "huntmaster", "kc-baselines",
            KcBaselineStoreTest.filename("account", "boss")).exists());
        store.close();
        store = new HuntmasterPlugin().createBaselineStore();
        assertEquals(Integer.valueOf(257), load().get("boss"));
    }

    @Test public void existingNewDirectoryDoesNotOverwriteEitherCopy() throws Exception
    {
        Filepath legacy = root.join("huntmaster", "kc-baselines");
        Filepath current = root.join("plugin-data", "huntmaster", "kc-baselines");
        legacy.createDirectories(); current.createDirectories();
        String name = KcBaselineStoreTest.filename("account", "boss");
        legacy.joinSegment(name).write("257"); current.joinSegment(name).write("290");
        assertEquals(Integer.valueOf(290), load().get("boss"));
        try (java.io.BufferedReader reader = legacy.joinSegment(name).openBufferedReader())
        { assertEquals("257", reader.readLine()); }
    }

    @Test public void freshInstallationSavesAndLoads() throws Exception
    {
        assertTrue(load().isEmpty());
        store.save("account", "boss", 1);
        assertEquals(Integer.valueOf(1), load().get("boss"));
    }

    @Test public void blockedMigrationLeavesLegacyDataAndCanRetry() throws Exception
    {
        Filepath legacy = root.join("huntmaster", "kc-baselines");
        legacy.createDirectories();
        legacy.joinSegment(KcBaselineStoreTest.filename("account", "boss")).write("257");
        root.join("plugin-data").write("blocks destination directory");
        assertTrue(load().isEmpty());
        assertTrue(legacy.exists());
        root.join("plugin-data").delete();
        assertEquals(Integer.valueOf(257), load().get("boss"));
    }

    private Map<String, Integer> load() throws Exception
    {
        CompletableFuture<Map<String, Integer>> loaded = new CompletableFuture<>();
        store.load("account", Collections.singleton("boss"), loaded::complete);
        return loaded.get(5, TimeUnit.SECONDS);
    }

    private void clearFixtures() throws Exception
    {
        for (String name : new String[]{"huntmaster", "plugin-data"})
        {
            Filepath fixture = root.joinSegment(name);
            if (fixture.exists()) fixture.deleteRecursively();
        }
    }
}

package com.huntmaster;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import org.junit.Test;
import static org.junit.Assert.*;

public class EncounterCaptureTest
{
	@Test public void serializedUnknownCounterBaselineIsExplicitNull()
	{
		EncounterObservation record = new EncounterObservation(UUID.randomUUID(), UUID.randomUUID(),
			"Example", "Scurrius", BossDetectorType.STANDARD_NPC, "observation-v1", 1000, 100, 10, true);
		record.recordCounter(101, EncounterObservation.CounterSource.KC_MESSAGE, null, 106);
		record.closeIfExpired(110);
		String wire = EncounterReportCodec.encode(record.snapshot()).toString();
		com.google.gson.JsonObject counter = new com.google.gson.JsonParser().parse(wire).getAsJsonObject()
			.getAsJsonArray("signals").get(0).getAsJsonObject();
		assertTrue(counter.has("previous"));
		assertTrue(counter.get("previous").isJsonNull());
	}
	@Test public void lateCounterRecoversEarlierDeathWithoutAwardingCredit()
	{
		List<EncounterObservation.Snapshot> output = new ArrayList<>();
		EncounterCapture c = new EncounterCapture(output::add);
		BossDetector d = new BossDetector(BossDefinition.betaCandidate("Sarachnis", "sarachnis", "Your Sarachnis kill count is:"));
		String id = UUID.randomUUID().toString();
		c.primary(d,"Example",id,100,1000,EncounterObservation.SignalKind.DEATH);
		c.advance(110);
		c.counter(d,"Example",id,112,8200,EncounterObservation.CounterSource.KC_MESSAGE,null,10);
		c.loot(d,"Example",id,113,8800);
		c.advance(122);
		EncounterObservation.Snapshot report=output.get(1);
		assertEquals(3,report.signals.size());
		assertEquals(EncounterObservation.SignalKind.DEATH,report.signals.get(0).kind);
		assertEquals(12,report.signals.get(1).tickOffset);
		assertNull(report.signals.get(1).previous);
		assertNull(report.creditEventId);
		assertTrue(report.evidenceOnly);
	}
	@Test public void signalHistoryIsBoundedAndCannotCrossAssignments()
	{
		EncounterSignalBuffer b=new EncounterSignalBuffer();
		for(int i=0;i<100;i++) b.add("old",10,1000,i%2==0?EncounterObservation.SignalKind.DEATH:EncounterObservation.SignalKind.LOOT);
		assertEquals(64,b.consume("old",10).size());
		b.add("old",10,1000,EncounterObservation.SignalKind.DEATH);
		assertTrue(b.consume("new",11).isEmpty());
		b.add("new",10,1000,EncounterObservation.SignalKind.DEATH);
		assertTrue(b.consume("new",27).isEmpty());
		b.add("new",30,1000,EncounterObservation.SignalKind.DEATH);
		assertTrue(b.consume("new",1).isEmpty());
	}
	private final BossDetector detector = new BossDetector(new BossDefinition("Brutus", "brutus", "Your Brutus", 12, "v1"));
	private final String assignment = UUID.randomUUID().toString();
	private final List<EncounterObservation.Snapshot> reports = new ArrayList<>();
	private final EncounterCapture capture = new EncounterCapture(reports::add);
	@Test public void verifiedCaptureKeepsLateLootAndCreditIdentity()
	{
		capture.primary(detector, "Example", assignment, 100, 1000, EncounterObservation.SignalKind.DEATH);
		capture.counter(detector, "Example", assignment, 101, 1600, EncounterObservation.CounterSource.KC_MESSAGE, 8, 9);
		UUID id = UUID.randomUUID(); capture.verified(id, EncounterObservation.Method.DEATH_AND_COUNTER);
		capture.loot(detector, "Example", assignment, 102, 2200);
		capture.advance(112);
		assertEquals(1, reports.size()); assertEquals(id, reports.get(0).creditEventId);
		assertEquals(3, reports.get(0).signals.size());
	}
	@Test public void overlappingEncountersRetainSeparateReportsAndUncertainLoot()
	{
		capture.primary(detector, "Example", assignment, 100, 1000, EncounterObservation.SignalKind.DEATH);
		capture.primary(detector, "Example", assignment, 104, 3400, EncounterObservation.SignalKind.DEATH);
		capture.loot(detector, "Example", assignment, 105, 4000);
		capture.advance(116);
		assertEquals(2, reports.size());
		assertEquals(EncounterObservation.LootAttribution.UNCERTAIN, reports.get(1).signals.get(1).attribution);
	}
	@Test public void changedAssignmentInterruptsOldEvidenceWithoutRebinding()
	{
		capture.primary(detector, "Example", assignment, 100, 1000, EncounterObservation.SignalKind.DEATH);
		String next = UUID.randomUUID().toString();
		capture.counter(detector, "Example", next, 101, 1600, EncounterObservation.CounterSource.KC_MESSAGE, null, 9);
		assertEquals(UUID.fromString(assignment), reports.get(0).assignmentId);
		assertEquals(EncounterObservation.Reason.ASSIGNMENT_CHANGED, reports.get(0).interruptionReason);
		capture.advance(113);
		assertEquals(UUID.fromString(next), reports.get(1).assignmentId);
		assertNull(reports.get(1).signals.get(0).previous);
	}
	@Test public void logoutPreservesVerifiedVerdictAndEndsCapture()
	{
		capture.primary(detector, "Example", assignment, 100, 1000, EncounterObservation.SignalKind.DEATH);
		capture.verified(UUID.randomUUID(), EncounterObservation.Method.DEATH_AND_LOOT);
		capture.interrupt(103, EncounterObservation.Reason.LOGOUT);
		assertEquals(EncounterObservation.Outcome.VERIFIED, reports.get(0).outcome);
		assertFalse(reports.get(0).captureComplete); capture.advance(120); assertEquals(1, reports.size());
	}
	@Test public void unknownCounterIsCapturedWithoutCredit()
	{
		capture.counter(detector, "Example", assignment, 100, 1000, EncounterObservation.CounterSource.KC_MESSAGE, null, 9);
		capture.advance(112); assertNull(reports.get(0).creditEventId);
		assertEquals(EncounterObservation.Outcome.UNRESOLVED, reports.get(0).outcome);
	}
	@Test public void wirePayloadMatchesBotNamingAndMillisecondTimestamp()
	{
		capture.counter(detector, "Example", assignment, 100, 1000, EncounterObservation.CounterSource.KC_MESSAGE, null, 9);
		capture.advance(112);
		com.google.gson.JsonObject body = EncounterReportCodec.encode(reports.get(0));
		assertEquals("1970-01-01T00:00:01.000Z", body.get("observedAt").getAsString());
		assertEquals("unresolved", body.get("outcome").getAsString());
		assertEquals("window_expired", body.get("reason").getAsString());
		assertTrue(body.getAsJsonArray("signals").get(0).getAsJsonObject().get("previous").isJsonNull());
		assertFalse(body.has("creditEventId"));
		System.out.println("ENCOUNTER_WIRE_FIXTURE=" + body);
	}
	@Test public void repeatedPrimaryInSameTickIsCoalesced()
	{
		capture.primary(detector, "Example", assignment, 100, 1000, EncounterObservation.SignalKind.DEATH);
		capture.primary(detector, "Example", assignment, 100, 1000, EncounterObservation.SignalKind.DEATH);
		capture.advance(112); assertEquals(1, reports.size()); assertEquals(1, reports.get(0).signals.size());
	}
	@Test public void verifiedInterruptedWirePayloadRetainsCreditReference()
	{
		capture.primary(detector, "Example", assignment, 100, 1000, EncounterObservation.SignalKind.DEATH);
		capture.counter(detector, "Example", assignment, 101, 1600, EncounterObservation.CounterSource.KC_MESSAGE, 8, 9);
		capture.verified(UUID.randomUUID(), EncounterObservation.Method.DEATH_AND_COUNTER);
		capture.interrupt(103, EncounterObservation.Reason.SHUTDOWN);
		System.out.println("ENCOUNTER_WIRE_FIXTURE=" + EncounterReportCodec.encode(reports.get(0)));
	}
}

package com.huntmaster;

import org.junit.Test;
import static org.junit.Assert.*;

public class VerificationTelemetryTest
{
	@Test
	public void noEvidenceHasNoRate()
	{
		VerificationTelemetry stats = new VerificationTelemetry();
		assertEquals(0, stats.getCompletedAttempts());
		assertNull(stats.getVerificationRate());
	}

	@Test
	public void mixedOutcomesUseCompletedAttemptsAsDenominator()
	{
		VerificationTelemetry stats = new VerificationTelemetry();
		stats.record(VerificationTelemetry.Outcome.VERIFIED);
		stats.record(VerificationTelemetry.Outcome.VERIFIED);
		stats.record(VerificationTelemetry.Outcome.UNRESOLVED);
		stats.record(VerificationTelemetry.Outcome.AMBIGUOUS);
		assertEquals(4, stats.getCompletedAttempts());
		assertEquals(2, stats.getVerified());
		assertEquals(1, stats.getUnresolved());
		assertEquals(1, stats.getAmbiguous());
		assertEquals(0.5, stats.getVerificationRate(), 0.000001);
	}

	@Test
	public void restoredCountersContinueAccumulating()
	{
		VerificationTelemetry stats = new VerificationTelemetry();
		stats.restore(8, 1, 1);
		stats.record(VerificationTelemetry.Outcome.UNRESOLVED);
		assertEquals(11, stats.getCompletedAttempts());
		assertEquals(8.0 / 11, stats.getVerificationRate(), 0.000001);
	}

	@Test
	public void invalidPersistedCountersCannotOverflowTotals()
	{
		VerificationTelemetry stats = new VerificationTelemetry();
		stats.restore(-1, Long.MAX_VALUE, Long.MAX_VALUE);
		stats.record(VerificationTelemetry.Outcome.UNRESOLVED);
		assertEquals(0, stats.getVerified());
		assertEquals(2_000_000_000_000L, stats.getCompletedAttempts());
		assertEquals(0.0, stats.getVerificationRate(), 0.0);
	}

	@Test
	public void separateDetectorsDoNotShareCounts()
	{
		VerificationTelemetry first = new VerificationTelemetry();
		VerificationTelemetry second = new VerificationTelemetry();
		first.record(VerificationTelemetry.Outcome.AMBIGUOUS);
		assertEquals(0, second.getCompletedAttempts());
		assertNull(second.getVerificationRate());
	}
}

package com.huntmaster;

import org.junit.Test;
import static org.junit.Assert.*;

public class ConnectionOutageStateTest
{
	private static final long START = 1_000_000L;

	@Test
	public void connectedStateDoesNotPause()
	{
		assertFalse(new ConnectionOutageState().isPaused(Long.MAX_VALUE));
	}

	@Test
	public void repeatedFailuresDoNotExtendGracePeriod()
	{
		ConnectionOutageState state = new ConnectionOutageState();
		assertTrue(state.fail(START));
		assertFalse(state.fail(START + 30_000));
		assertEquals(START, state.getStartedAt());
		assertFalse(state.isPaused(START + ConnectionOutageState.GRACE_PERIOD_MS - 1));
		assertTrue(state.isPaused(START + ConnectionOutageState.GRACE_PERIOD_MS));
	}

	@Test
	public void restartPreservesRemainingGracePeriod()
	{
		ConnectionOutageState restored = new ConnectionOutageState();
		restored.restore(START, START + 5 * 60_000);
		assertEquals(START, restored.getStartedAt());
		assertFalse(restored.isPaused(START + 9 * 60_000));
		assertTrue(restored.isPaused(START + 10 * 60_000));
	}

	@Test
	public void restartAfterDeadlineStaysPaused()
	{
		ConnectionOutageState restored = new ConnectionOutageState();
		restored.restore(START, START + 20 * 60_000);
		assertTrue(restored.isPaused(START + 20 * 60_000));
	}

	@Test
	public void recoveryStartsFreshGracePeriodForNextOutage()
	{
		ConnectionOutageState state = new ConnectionOutageState();
		state.fail(START);
		state.recover();
		assertEquals(0, state.getStartedAt());
		assertFalse(state.isPaused(START + 20 * 60_000));
		assertTrue(state.fail(START + 30 * 60_000));
		assertFalse(state.isPaused(START + 39 * 60_000));
	}

	@Test
	public void invalidRestoredTimestampsDoNotBreakDeadline()
	{
		ConnectionOutageState state = new ConnectionOutageState();
		state.restore(-1, START);
		assertEquals(0, state.getStartedAt());
		state.restore(START + 60_000, START);
		assertEquals(START, state.getStartedAt());
		assertTrue(state.isPaused(START + ConnectionOutageState.GRACE_PERIOD_MS));
	}
}

package com.huntmaster;

import org.junit.Test;
import static org.junit.Assert.*;

public class VerificationReliabilityStateTest
{
	@Test
	public void thirdFailurePausesAndFurtherFailuresDoNotAccumulate()
	{
		VerificationReliabilityState state = new VerificationReliabilityState();
		assertTrue(state.recordFailure());
		assertTrue(state.recordFailure());
		assertFalse(state.isPaused());
		assertTrue(state.recordFailure());
		assertTrue(state.isPaused());
		assertFalse(state.recordFailure());
		assertEquals(3, state.getFailures());
	}

	@Test
	public void verifiedKillBreaksFailureStreakBeforePause()
	{
		VerificationReliabilityState state = new VerificationReliabilityState();
		state.recordFailure();
		state.recordFailure();
		state.recordVerified();
		assertEquals(0, state.getFailures());
		state.recordFailure();
		assertFalse(state.isPaused());
	}

	@Test
	public void lateVerifiedSignalDoesNotResumePausedTracking()
	{
		VerificationReliabilityState state = new VerificationReliabilityState();
		state.restore(3);
		state.recordVerified();
		assertTrue(state.isPaused());
	}

	@Test
	public void persistedFailuresPreserveThresholdAndClampInvalidCounts()
	{
		VerificationReliabilityState state = new VerificationReliabilityState();
		state.restore(2);
		state.recordFailure();
		assertTrue(state.isPaused());
		state.restore(-1);
		assertEquals(0, state.getFailures());
		state.restore(Integer.MAX_VALUE);
		assertEquals(3, state.getFailures());
	}
}

package com.huntmaster;

