    {
        assertTrue(BossNpcAliases.matches("Grotesque Guardians", "Dusk"));
        assertTrue(BossNpcAliases.matches("Grotesque Guardians", "Dawn"));
        assertTrue(BossNpcAliases.matches("Royal Titans", "Branda the Fire Queen"));
