package com.huntmaster;

import java.util.*;

/** Small diagnostic history. Contains no chat, location, items, or other-player information. */
final class EncounterSignalBuffer
{
    static final int HISTORY_TICKS = 16;
    static final int MAX_EVENTS = 64;
    static final class Event
    {
        final int tick;
        final long time;
        final EncounterObservation.SignalKind kind;
        Event(int tick, long time, EncounterObservation.SignalKind kind)
        { this.tick = tick; this.time = time; this.kind = kind; }
    }
    private final List<Event> events = new ArrayList<>();
    private String context;
    void add(String key, int tick, long time, EncounterObservation.SignalKind kind)
    {
        prune(key, tick);
        if (!events.isEmpty())
        {
            Event last = events.get(events.size()-1);
            if (last.tick == tick && last.kind == kind) return;
        }
        if (events.size() == MAX_EVENTS) events.remove(0);
        events.add(new Event(tick, time, kind));
    }
    List<Event> consume(String key, int tick)
    {
        prune(key, tick);
        List<Event> result = new ArrayList<>(events);
        events.clear();
        return result;
    }
    private void prune(String key, int tick)
    {
        if (!Objects.equals(context, key) || (!events.isEmpty() && events.get(events.size()-1).tick > tick)) clear();
        context = key;
        events.removeIf(event -> tick-event.tick > HISTORY_TICKS);
    }
    void clear() { events.clear(); context = null; }
}

package com.huntmaster;

/** Outage time is independent of queued-event age and survives client restarts. */
final class ConnectionOutageState
{
	static final long GRACE_PERIOD_MS = 10 * 60 * 1000L;
	private long startedAt;

	void restore(long savedStartedAt, long now)
	{
		startedAt = savedStartedAt > 0 ? Math.min(savedStartedAt, now) : 0;
	}

	boolean fail(long now)
	{
		if (startedAt != 0)
		{
			return false;
		}
		startedAt = now;
		return true;
	}

	boolean isPaused(long now)
	{
		return startedAt != 0 && now - startedAt >= GRACE_PERIOD_MS;
	}

	long getStartedAt()
	{
		return startedAt;
	}

	void recover()
	{
		startedAt = 0;
	}
}

package com.huntmaster;

/** Session/assignment-scoped sampled total. Initial reads are baselines, never credit. */
final class AssignedTotalTracker
{
    private String scope;
    private Integer previous;
    private int lastTick = -1;
    Integer changed(String nextScope, int total, int tick)
    {
        if (!nextScope.equals(scope) || tick < lastTick) { scope = nextScope; previous = null; }
        lastTick = tick;
        Integer old = previous;
        previous = total;
        return old != null && old != total ? old : null;
    }
    void clear() { scope = null; previous = null; lastTick = -1; }
}

