package com.huntmaster;

import java.util.Locale;
import java.util.regex.*;
import net.runelite.client.util.Text;

/** Conservative counterpart to RuneLite Chat Commands' shared personal-counter parser. */
final class GenericKcRouter
{
    private static final Pattern COUNTER = Pattern.compile(
        "^Your (?:completion count for |subdued |completed )?(.+?) (?:kill |harvest |completion |success )?(?:count )?is: ?([0-9][0-9,]*)(?:\\.|$|\\s)", Pattern.CASE_INSENSITIVE);
    static boolean eligible(String assignedBoss)
    {
        if (assignedBoss == null || assignedBoss.trim().isEmpty()) return false;
        String name = assignedBoss.toLowerCase(Locale.ROOT);
        return !name.contains("chambers of xeric") && !name.contains("theatre of blood")
            && !name.contains("tombs of amascut");
    }
    static Integer parse(String message, String assignedBoss)
    {
        if (!eligible(assignedBoss) || message == null || message.length() > 1024) return null;
        Matcher match = COUNTER.matcher(Text.removeTags(message));
        if (!match.find() || !BossCounterAliases.matches(assignedBoss, match.group(1).trim())) return null;
        try { return Integer.valueOf(match.group(2).replace(",", "")); }
        catch (NumberFormatException ex) { return null; }
    }
}

package com.huntmaster;

import okhttp3.HttpUrl;
import okhttp3.Request;

/** Fixed-origin request guard. RSN registration and membership are checked by the bot. */
final class PluginLink
{
	Request authenticate(Request request, String endpoint)
	{
		HttpUrl origin = HttpUrl.parse(endpoint);
		HttpUrl target = request.url();
		if (origin == null || !origin.scheme().equals(target.scheme()) || !origin.host().equals(target.host())
			|| origin.port() != target.port()) throw new IllegalArgumentException("unexpected_bot_origin");
		Request.Builder builder = request.newBuilder().removeHeader("Authorization");
		return builder.build();
	}
}

package com.huntmaster;

import java.io.IOException;
import java.io.InputStream;
import java.net.URI;
import java.net.URISyntaxException;
import java.util.Properties;

/** A packaged bot address; players cannot select another server. */
final class BotEndpoint
{
	static String resolve(boolean development, String publicAddress)
	{
		if (development) return "http://127.0.0.1:8787";
		if (publicAddress == null || publicAddress.trim().isEmpty()) return null;
		try
		{
			URI uri = new URI(publicAddress.trim());
			String host = uri.getHost();
			if (!"https".equals(uri.getScheme()) || host == null || host.indexOf('.') < 0
				|| "localhost".equalsIgnoreCase(host) || host.matches("[0-9.]+")
				|| host.indexOf(':') >= 0 || uri.getUserInfo() != null || uri.getPort() != -1
				|| uri.getQuery() != null || uri.getFragment() != null
				|| !(uri.getPath().isEmpty() || "/".equals(uri.getPath()))) return null;
			return "https://" + host;
		}
		catch (URISyntaxException ex) { return null; }
	}

	static String load(boolean development)
	{
		if (development) return resolve(true, null);
		Properties properties = new Properties();
		try (InputStream input = BotEndpoint.class.getResourceAsStream("/huntmaster-api.properties"))
		{
			if (input != null) properties.load(input);
			if (!Boolean.parseBoolean(properties.getProperty("publicReady", "false"))) return null;
			return resolve(false, properties.getProperty("botUrl"));
		}
		catch (IOException ex) { return null; }
	}
}

